477	function parseThresholds(rawThresholds?: string[]): Record<string, number> {
478	  const result: Record<string, number> = {};
479	  if (!rawThresholds || rawThresholds.length === 0) {
480	    return result;
481	  }
482	
483	  for (const raw of rawThresholds) {
484	    const [metric, minStr] = raw.split('=');
485	    if (!metric || !minStr) {
486	      throw new Error(`Malformed threshold: "${raw}". Expected format: <metric>=<number>`);
487	    }
488	    const min = Number.parseFloat(minStr);
489	    if (Number.isNaN(min)) {
490	      throw new Error(`Invalid threshold value for "${metric}": "${minStr}" is not a number.`);
491	    }
492	    if (min < 0 || min > 1) {
493	      throw new Error(`Invalid threshold value for "${metric}": ${min} is outside the range [0, 1].`);
494	    }
495	    result[metric] = min;
496	  }
497	  return result;
498	}
499	
500	function validateThresholdMetrics(
501	  thresholds: Record<string, number>,
502	  evaluations: Array<{ id: string }>
503	): string[] {
504	  const validMetricIds = new Set(evaluations.map((m) => m.id));
505	  const errors: string[] = [];
506	  for (const metric of Object.keys(thresholds)) {
507	    if (!validMetricIds.has(metric)) {
508	      errors.push(metric);
509	    }
510	  }
511	  return errors;
512	}
