514	function runEvalCommand(options: EvalOptions) {
515	  assertFileExists(options.outputs);
516	
517	  let parsedThresholds: Record<string, number>;
518	  try {
519	    parsedThresholds = parseThresholds(options.threshold);
520	  } catch (error) {
521	    log.error((error as Error).message);
522	    process.exit(2);
523	  }
524	
525	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
526	    outputsPath: options.outputs,
527	    referencesPath: options.references
528	  });
529	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
530	    outputs: dataset.outputs,
531	    references: dataset.references
532	  });
533	
534	  const unknownMetrics = validateThresholdMetrics(parsedThresholds, evaluations);
535	  if (unknownMetrics.length > 0) {
536	    const validIds = evaluations.map((m: { id: string }) => m.id);
537	    log.error(`Unknown metric(s): ${unknownMetrics.join(', ')}. Valid metrics: ${validIds.join(', ')}`);
538	    process.exit(2);
539	  }
540	
541	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
542	    evaluations,
543	    outputsPath: dataset.outputsPath,
544	    referencesPath: dataset.referencesPath,
545	    thresholds: parsedThresholds
546	  });
547	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
548	    report,
549	    format: options.format ?? 'json',
550	    reportPath: options.report
551	  });
552	  log.success('Evaluation report generated.', { path: resolvedPath });
553	
554	  if (report.passed === false) {
555	    process.exit(1);
556	  }
557	}
