// Simulate the fixed parseThresholds with each problematic input
function testThreshold(raw) {
  const eqIndex = raw.indexOf('=');
  if (eqIndex === -1) {
    return { valid: false, error: 'Malformed' };
  }
  const metric = raw.substring(0, eqIndex);
  const minStr = raw.substring(eqIndex + 1);
  if (!metric || !minStr) {
    return { valid: false, error: 'Empty metric or value' };
  }
  const min = Number(minStr);
  if (Number.isNaN(min) || String(min) !== minStr) {
    return { valid: false, error: 'Invalid number' };
  }
  if (min < 0 || min > 1) {
    return { valid: false, error: 'Outside [0,1]' };
  }
  return { valid: true, value: min };
}

const cases = [
  'exact_match=0.9abc',    // Problem 2a
  'exact_match=0.5=x',     // Problem 2b
  'exact_match=0x1',       // Problem 2c (worst case)
  'exact_match=0.5',       // Should pass
  '__proto__=0.5'          // Will be caught as unknown metric
];

cases.forEach(tc => {
  const result = testThreshold(tc);
  console.log(\`\${tc.padEnd(25)} → \${JSON.stringify(result)}\`);
});
"

